function confirmRemoval(){return new Promise(resolve=>{const dialog=document.createElement('dialog'),title=document.createElement('h2'),text=document.createElement('p'),actions=document.createElement('div'),back=document.createElement('button'),remove=document.createElement('button');title.textContent='Eliminar testimonio';text.textContent='Se retirará esta imagen de la galería y de la página pública.';actions.className='management-actions';back.textContent='Cancelar';remove.textContent='Eliminar';remove.className='danger';back.type=remove.type='button';back.addEventListener('click',()=>dialog.close('cancel'));remove.addEventListener('click',()=>dialog.close('remove'));dialog.addEventListener('close',()=>{const approved=dialog.returnValue==='remove';dialog.remove();resolve(approved);},{once:true});dialog.append(title,text,actions);actions.append(back,remove);document.body.append(dialog);dialog.showModal();back.focus();});}
import {receiptFile} from './receipt-file.js';
export function initTestimonials({call}){
 const $=id=>document.getElementById(id);let busy=false,generation=0,requestId=null;
 function show(testimonials){$('admin-business').hidden=testimonials;$('testimonials-panel').hidden=!testimonials;$('business-tab').classList.toggle('selected',!testimonials);$('testimonials-tab').classList.toggle('selected',testimonials);}
 function render(items){const list=$('testimonial-list');list.replaceChildren();$('testimonial-count').textContent=items.length+' / 12 imágenes';for(const item of items){const card=document.createElement('article'),img=document.createElement('img'),title=document.createElement('p'),button=document.createElement('button');img.src='https://pitstop-cbe24.web.app/api/public?image='+item.id;img.alt=item.caption;img.loading='lazy';title.textContent=item.caption;button.textContent='×';button.type='button';button.className='testimonial-remove';button.title='Eliminar testimonio';button.setAttribute('aria-label','Eliminar testimonio: '+item.caption);button.addEventListener('click',async()=>{if(busy)return;busy=true;if(!await confirmRemoval()){busy=false;return;}button.disabled=true;const stamp=generation;try{const {data}=await call('ownerTestimonials',{action:'remove',id:item.id});if(stamp!==generation)return;render(data.items);$('testimonial-state').textContent='Testimonio retirado. El cambio puede tardar un minuto en verse en la página pública.';}catch{$('testimonial-state').textContent='No se pudo retirar el testimonio.';}finally{busy=false;button.disabled=false;}});card.className='testimonial-tile';card.append(img,title,button);list.append(card);}}
 async function load(){const stamp=++generation;$('testimonial-state').textContent='Cargando…';try{const {data}=await call('ownerTestimonials',{action:'list'});if(stamp!==generation)return;render(data.items);$('testimonial-state').textContent=data.items.length?`${data.items.length} testimonios publicados.`:'Todavía no hay testimonios publicados.';}catch{if(stamp===generation)$('testimonial-state').textContent='No se pudo cargar. Revisa tu acceso y vuelve a intentarlo.';}}
 $('business-tab').addEventListener('click',()=>show(false));$('testimonials-tab').addEventListener('click',()=>{show(true);load();});
 $('testimonial-form').addEventListener('input',()=>{requestId=null;});
 $('testimonial-form').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;const stamp=generation;$('testimonial-fields').disabled=true;$('testimonial-state').textContent='Publicando…';requestId??=crypto.randomUUID();try{const image=await receiptFile($('testimonial-image').files[0]);if(!image)throw new Error();const {data}=await call('ownerTestimonials',{action:'publish',id:requestId,caption:$('testimonial-caption').value.trim(),image});if(stamp!==generation)return;render(data.items);$('testimonial-form').reset();requestId=null;$('testimonial-state').textContent='Publicado. Aparecerá en la página pública en aproximadamente un minuto.';}catch{$('testimonial-state').textContent='No se pudo publicar. Usa una imagen de hasta 4 MB y revisa si ya tienes 12 testimonios.';}finally{busy=false;$('testimonial-fields').disabled=false;}});
 return ()=>{generation++;$('testimonial-form').reset();$('testimonial-list').replaceChildren();$('testimonial-state').textContent='';show(false);};
}
